def main() -> None:
    """Extract the untouched original page and launch it in a browser."""
    try:
        html_bytes = zlib.decompress(base64.b85decode(_HTML_PAYLOAD_B85.encode("ascii")))
    except Exception as exc:
        raise RuntimeError("NEXUS HTML data could not be decoded.") from exc

    actual_hash = hashlib.sha256(html_bytes).hexdigest()
    if actual_hash != _HTML_SHA256:
        raise RuntimeError("NEXUS HTML integrity check failed; refusing to launch a changed file.")

    launch_dir = Path(tempfile.mkdtemp(prefix="NEXUS_SUPER3.1_"))
    html_path = launch_dir / "NEXUS_SUPER3.1.html"
    html_path.write_bytes(html_bytes)

    page_url = html_path.resolve().as_uri()
    print("NEXUS SUPER3.1 をブラウザで起動します。")
    print(f"展開先: {html_path}")
    opened = webbrowser.open_new_tab(page_url)
    if not opened:
        print("ブラウザを自動起動できませんでした。次のファイルをブラウザで開いてください:")
        print(html_path)


if __name__ == "__main__":
    main()
